"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["11443"],{8161(e){e.exports=JSON.parse('{"id":"F410","slug":"heston-variance","name":"Heston Model: Average Variance and Feller Condition","subject":"Quantitative Finance","section":"Quant","topic":"Stochastic volatility models (Heston)","level":"Beginner","aliases":["stochastic volatility","Heston","variance mean reversion","vol of vol"],"formula":{"latex":"E[\\\\bar{v}_{T}]=\\\\theta+(v_{0}-\\\\theta)\\\\frac{1-e^{-\\\\kappa T}}{\\\\kappa T},\\\\quad 2\\\\kappa\\\\theta\\\\ge\\\\xi^{2}","also":[],"text":"Expected average variance over T = theta + (v0 - theta) x (1 - e^(-kappa T)) / (kappa T); variance stays above zero if 2 x kappa x theta >= xi^2"},"symbols":[{"symbol":"v_0","meaning":"Current variance (volatility squared)","unit":"per year"},{"symbol":"theta","meaning":"Long-run variance","unit":"per year"},{"symbol":"kappa","meaning":"Speed at which variance reverts","unit":"per year"},{"symbol":"xi","meaning":"Volatility of variance (\\"vol of vol\\")","unit":"number"},{"symbol":"rho","meaning":"Correlation between stock and variance shocks. Negative values create skew","unit":"number"}],"when_to_use":"Use it to understand what the Heston model says about volatility. Variance follows a CIR process: it reverts to a long-run level and is random. The expected average variance over the option\'s life, rather than today\'s variance, drives the option price level, while rho and xi shape the skew and smile.","worked_example":{"problem":"Current volatility is 24.5% (variance 0.06) and the long-run volatility is 20% (variance 0.04). The speed is 2, the vol of vol is 0.5 and the horizon is 1 year.","inputs":{"v0":0.06,"th":0.04,"k":2,"xi":0.5,"t":1},"steps":[{"label":"Expected average variance = theta + (v0 - theta)(1 - e^(-kappa T)) / (kappa T)","working":"0.04+(0.06-0.04) x (1-exp(-2 x 1)) / (2 x 1)","value":"0.04865"},{"label":"Average volatility = sqrt(average variance)","working":"sqrt(0.0486466)","value":"22.06%"},{"label":"Current volatility","working":"sqrt(0.06)","value":"24.49%"},{"label":"Long-run volatility","working":"sqrt(0.04)","value":"20.00%"},{"label":"2 x kappa x theta","working":"2 x 2 x 0.04","value":"0.1600"},{"label":"xi squared","working":"0.5^2","value":"0.2500"},{"label":"Feller condition holds? (1 = yes, 0 = no)","working":"1 if 0.16>=0.25 else 0","value":"0"}],"answer":"The expected average variance over the year is 0.04865, which is an average volatility of 22.06%, between the current 24.49% and the long-run 20.00%. The Feller test compares 2 kappa theta = 0.1600 with xi squared = 0.2500. The condition fails, so variance can reach zero."},"calculator":{"available":true,"inputs":[{"id":"v0","label":"Current variance","unit":"","type":"number","default":0.06,"hint":""},{"id":"th","label":"Long-run variance","unit":"","type":"number","default":0.04,"hint":""},{"id":"k","label":"Speed of reversion","unit":"","type":"number","default":2,"hint":""},{"id":"xi","label":"Vol of vol","unit":"","type":"number","default":0.5,"hint":""},{"id":"t","label":"Horizon","unit":"years","type":"number","default":1,"hint":"","min":0.1}],"checks":[{"expr":"v0>0 and th>0 and k>0 and xi>0","message":"Enter positive values."}],"steps":[{"id":"avg","label":"Expected average variance = theta + (v0 - theta)(1 - e^(-kappa T)) / (kappa T)","expr":"th+(v0-th)*(1-exp(-k*t))/(k*t)","format":"num5"},{"id":"avgvol","label":"Average volatility = sqrt(average variance)","expr":"sqrt(avg)","format":"pct2"},{"id":"vol0","label":"Current volatility","expr":"sqrt(v0)","format":"pct2"},{"id":"volth","label":"Long-run volatility","expr":"sqrt(th)","format":"pct2"},{"id":"lhs","label":"2 x kappa x theta","expr":"2*k*th","format":"num4"},{"id":"rhs","label":"xi squared","expr":"xi^2","format":"num4"},{"id":"ok","label":"Feller condition holds? (1 = yes, 0 = no)","expr":"1 if lhs>=rhs else 0","format":"num0"}],"results":["avg","avgvol","ok"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"avg":0.04864664716763387,"avgvol":0.220559849400642,"vol0":0.2449489742783178,"volth":0.2,"lhs":0.16,"rhs":0.25,"ok":0}},"finder":{"finds":"The volatility level Heston expects over a horizon","needs":"Current and long-run variance, speed, vol of vol"},"related":[{"slug":"cir-moments-feller","name":"Cox-Ingersoll-Ross Moments and Feller Condition"},{"slug":"implied-volatility","name":"Implied Volatility"},{"slug":"garch-forecast","name":"GARCH(1,1) Variance Forecast"}],"related_ids":["F408","F335","F412"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>E</mi><mo stretchy=\\"false\\">[</mo><msub><mover accent=\\"true\\"><mi>v</mi><mo>\u02C9</mo></mover><mi>T</mi></msub><mo stretchy=\\"false\\">]</mo><mo>=</mo><mi>\u03B8</mi><mo>+</mo><mo stretchy=\\"false\\">(</mo><msub><mi>v</mi><mn>0</mn></msub><mo>\u2212</mo><mi>\u03B8</mi><mo stretchy=\\"false\\">)</mo><mfrac><mrow><mn>1</mn><mo>\u2212</mo><msup><mi>e</mi><mrow><mo>\u2212</mo><mi>\u03BA</mi><mi>T</mi></mrow></msup></mrow><mrow><mi>\u03BA</mi><mi>T</mi></mrow></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mn>2</mn><mi>\u03BA</mi><mi>\u03B8</mi><mo>\u2265</mo><msup><mi>\u03BE</mi><mn>2</mn></msup></mrow><annotation encoding=\\"application/x-tex\\">E[\\\\bar{v}_{T}]=\\\\theta+(v_{0}-\\\\theta)\\\\frac{1-e^{-\\\\kappa T}}{\\\\kappa T},\\\\quad 2\\\\kappa\\\\theta\\\\ge\\\\xi^{2}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"herfindahl-index","name":"Herfindahl-Hirschman Index (Industry Concentration)"},"next":{"slug":"holding-period-return","name":"Holding Period Return"},"lesson":null,"total":522}')}}]);